const logger = createLogger("DataGrid");

export function updateColumnVisibility(grid: any, visibleColumns: string[], skipURLUpdate: boolean = false): void {
    if (!grid.tableEl) return;

    const visibleSet = new Set(visibleColumns);

    // Update hidden columns state
    grid.state.hiddenColumns.clear();
    grid.config.columns.forEach(col => {
      if (!visibleSet.has(col.field)) {
        grid.state.hiddenColumns.add(col.field);
      }
    });

    // Update URL with new hidden columns state (unless during restoration)
    if (!skipURLUpdate) {
      grid.pushStateToURL();
    }

    // Update header and filter row visibility
    // Note: This selector matches both header row th[data-column] and filter row th[data-column]
    // Filter row cells must have data-column attributes to stay aligned with headers
    const headerCells = grid.tableEl.querySelectorAll('thead th[data-column]');
    headerCells.forEach((th) => {
      const field = (th as HTMLElement).dataset.column;
      if (field) {
        (th as HTMLElement).style.display = visibleSet.has(field) ? '' : 'none';
      }
    });

    // Update body cell visibility
    const bodyCells = grid.tableEl.querySelectorAll('tbody td[data-column]');
    bodyCells.forEach((td) => {
      const field = (td as HTMLElement).dataset.column;
      if (field) {
        (td as HTMLElement).style.display = visibleSet.has(field) ? '' : 'none';
      }
    });

    // Sync checkbox state in column visibility menu
    grid.syncColumnVisibilityCheckboxes();
  }

  /**
   * Sync column visibility switches with current state
   * Uses ColumnManager if available, falls back to direct DOM manipulation
   */
export function syncColumnVisibilityCheckboxes(grid: any): void {
    // Prefer ColumnManager if initialized
    if (grid.columnManager) {
      grid.columnManager.syncWithGridState();
      return;
    }

    // Fallback to direct DOM manipulation for legacy checkboxes
    const menu = document.querySelector(grid.selectors.columnToggleMenu);
    if (!menu) return;

    grid.config.columns.forEach(col => {
      const checkbox = menu.querySelector<HTMLInputElement>(
        `input[data-column="${col.field}"]`
      );
      if (checkbox) {
        checkbox.checked = !grid.state.hiddenColumns.has(col.field);
      }
    });
  }

function removeDataGridStateRows(tbody: HTMLElement): void {
  tbody.querySelectorAll('[data-datagrid-state]').forEach((row) => row.remove());
}

export function syncActionColumnStructure(grid: any): void {
  if (!grid.tableEl || hasActionColumn(grid)) return;

  grid.tableEl
    .querySelectorAll('thead [data-role="actions"]')
    .forEach((cell: HTMLElement) => cell.remove());
}

function createDataGridStateRow(
  grid: any,
  state: 'loading' | 'error',
  message: string,
): HTMLTableRowElement {
  const row = document.createElement('tr');
  row.className = 'admin-datagrid__state-row';
  row.dataset.datagridState = state;

  const cell = document.createElement('td');
  cell.colSpan = structuralColumnCount(grid);
  cell.className = `admin-datagrid__state admin-datagrid__state--${state} px-6 py-8 text-center`;
  cell.setAttribute('role', state === 'error' ? 'alert' : 'status');
  cell.setAttribute('aria-live', state === 'error' ? 'assertive' : 'polite');
  cell.textContent = message;
  row.appendChild(cell);
  return row;
}

export function renderLoadingState(grid: any): void {
  const tbody = grid.tableEl?.querySelector('tbody');
  if (!tbody) return;

  removeDataGridStateRows(tbody);
  if (tbody.children.length > 0) {
    return;
  }
  if (grid.isGroupedViewActive()) {
    tbody.insertAdjacentHTML(
      'beforeend',
      renderGroupedLoadingState(grid.config.columns.length, fixedColumnCount(grid)),
    );
    return;
  }
  tbody.appendChild(createDataGridStateRow(grid, 'loading', 'Loading…'));
}

export function renderErrorState(grid: any, message: string): void {
  const tbody = grid.tableEl?.querySelector('tbody');
  if (!tbody) return;

  removeDataGridStateRows(tbody);
  if (grid.isGroupedViewActive()) {
    tbody.insertAdjacentHTML(
      'afterbegin',
      renderGroupedErrorState(grid.config.columns.length, message, undefined, fixedColumnCount(grid)),
    );
    return;
  }
  tbody.prepend(createDataGridStateRow(grid, 'error', message));
}

  /**
   * Render data into table
   */
export function renderData(grid: any, data: ApiResponse): void {
    const tbody = grid.tableEl?.querySelector('tbody');
    if (!tbody) {
      logger.error('[DataGrid] tbody not found!');
      return;
    }

    grid.actionMenuController?.closeAll();
    tbody.innerHTML = '';

    const items = data.data || data.records || [];
    logger.debug(`[DataGrid] renderData() called with ${items.length} items`);
    logger.debug('[DataGrid] First 3 items:', items.slice(0, 3));
    const total = grid.getResponseTotal(data);
    grid.state.totalRows = total ?? items.length;

    if (items.length === 0) {
      // Use grouped empty state if in grouped mode
      if (grid.isGroupedViewActive()) {
        tbody.innerHTML = renderGroupedEmptyState(
          grid.config.columns.length,
          fixedColumnCount(grid),
        );
      } else {
        tbody.innerHTML = `
          <tr class="admin-datagrid__state-row" data-datagrid-state="empty">
            <td colspan="${structuralColumnCount(grid)}" class="admin-datagrid__state admin-datagrid__state--empty px-6 py-8 text-center text-gray-500">
              No results found
            </td>
          </tr>
        `;
      }
      grid.setRenderState('empty');
      return;
    }

    // Clear records by ID cache
    grid.recordsById = Object.create(null);

    // Phase 2: Check if grouped mode is enabled and active
    if (grid.isGroupedViewActive()) {
      grid.renderGroupedData(data, items, tbody);
    } else {
      // Flat mode rendering (original behavior)
      grid.renderFlatData(items, tbody);
    }

    // Apply column visibility to new body cells
    // Note: config.columns is already in the correct order, but some may be hidden
    if (grid.state.hiddenColumns.size > 0) {
      const bodyCells = tbody.querySelectorAll('td[data-column]');
      bodyCells.forEach((td) => {
        const field = (td as HTMLElement).dataset.column;
        if (field && grid.state.hiddenColumns.has(field)) {
          (td as HTMLElement).style.display = 'none';
        }
      });
    }

    // Rebind selection after rendering
    if (grid.isCapabilityEnabled('selection')) {
      grid.updateSelectionBindings();
    }
    grid.setRenderState('ready');
  }

  /**
   * Render data in flat mode (original behavior)
   */
export function renderFlatData(grid: any, items: any[], tbody: HTMLElement): void {
    items.forEach((item: any, index: number) => {
      logger.debug(`[DataGrid] Rendering row ${index + 1}: id=${item.id}`);
      if (item.id) {
        grid.recordsById[item.id] = item;
      }
      const row = grid.createTableRow(item);
      tbody.appendChild(row);
    });

    logger.debug(`[DataGrid] Finished appending ${items.length} rows to tbody`);
    logger.debug(`[DataGrid] tbody.children.length =`, tbody.children.length);
  }

  /**
   * Render data in grouped mode (Phase 2)
   */
export function resolveRendererOptions(grid: any, col: ColumnDefinition): Record<string, any> {
    const options = col.rendererOptions ?? col.renderer_options;
    if (!options || typeof options !== 'object' || Array.isArray(options)) {
      return {};
    }
    return options;
  }

  /**
   * Create table row element
   */
export function createTableRow(grid: any, item: any): HTMLTableRowElement {
    const row = document.createElement('tr');

    // Apply custom row classes if provider is configured
    let rowClasses = ['admin-datagrid__row', 'hover:bg-gray-50'];
    if (grid.config.rowClassProvider) {
      rowClasses = rowClasses.concat(grid.config.rowClassProvider(item));
    }
    row.className = rowClasses.join(' ');

    if (grid.isCapabilityEnabled('selection')) {
      const checkboxCell = document.createElement('td');
      checkboxCell.className = 'admin-datagrid__cell px-6 py-4 whitespace-nowrap';
      checkboxCell.dataset.role = 'selection';
      checkboxCell.dataset.fixed = 'left';
      checkboxCell.innerHTML = `
        <label class="flex">
          <input type="checkbox"
                 class="table-checkbox shrink-0 border-gray-300 rounded text-blue-600 focus:ring-blue-500"
                 data-id="${escapeAttr(item.id)}">
          <span class="sr-only">Select</span>
        </label>
      `;
      row.appendChild(checkboxCell);
    }

    // Data cells
    grid.config.columns.forEach((col) => {
      const cell = document.createElement('td');
      cell.className = 'admin-datagrid__cell px-6 py-4 whitespace-nowrap text-sm text-gray-800';
      cell.setAttribute('data-column', col.field);

      const value = item[col.field];
      const rendererName = typeof col.renderer === 'string' ? col.renderer.trim() : '';
      const rendererContext: CellRendererContext = {
        options: grid.resolveRendererOptions(col),
      };

      // Priority: column render > field renderer > named renderer > default renderer
      if (col.render) {
        cell.innerHTML = col.render(value, item);
      } else if (grid.cellRendererRegistry.has(col.field)) {
        const renderer = grid.cellRendererRegistry.get(col.field);
        cell.innerHTML = renderer(value, item, col.field, rendererContext);
      } else if (rendererName && grid.cellRendererRegistry.has(rendererName)) {
        const renderer = grid.cellRendererRegistry.get(rendererName);
        cell.innerHTML = renderer(value, item, col.field, rendererContext);
      } else if (value === null || value === undefined) {
        cell.textContent = '-';
      } else if (col.field.includes('_at')) {
        const date = parseDateLike(value);
        cell.textContent = date ? date.toLocaleDateString() : String(value);
      } else {
        cell.textContent = String(value);
      }

      row.appendChild(cell);
    });

    if (!hasActionColumn(grid)) {
      return row;
    }

    // Actions cell
    const actionBase = grid.config.actionBasePath || grid.config.apiEndpoint;
    const actionsCell = document.createElement('td');
    actionsCell.className = 'admin-datagrid__cell admin-datagrid__actions px-6 py-4 whitespace-nowrap text-end text-sm font-medium';
    actionsCell.dataset.role = 'actions';
    actionsCell.dataset.fixed = 'right';

    const bindRenderedActions = (actions: any[]) => {
      actionsCell.innerHTML = grid.actionRenderer.renderRowActions(item, actions);
      grid.actionRenderer.attachRowActionListeners(actionsCell, actions, item, {
        onError: async (error: unknown, action: any) => {
          const structured = getStructuredActionError(error);
          if (structured?.textCode) {
            await grid.refresh();
          }
          if (!isHandledActionError(error)) {
            const errorMsg = error instanceof Error ? error.message : `Action "${action.label}" failed`;
            grid.notify(errorMsg, 'error');
          }
        },
      });
    };

    // Use custom row actions if provided, otherwise use default actions
    if (grid.config.rowActions) {
      const actions = grid.config.rowActions(item);
      bindRenderedActions(actions);
    } else if (grid.config.useDefaultActions !== false) {
      // Default actions (view, edit, delete)
      const defaultActions = [
        {
          label: 'View',
          icon: 'eye',
          action: () => { window.location.href = `${actionBase}/${item.id}`; },
          variant: 'secondary' as const
        },
        {
          label: 'Edit',
          icon: 'edit',
          action: () => { window.location.href = `${actionBase}/${item.id}/edit`; },
          variant: 'primary' as const
        },
        {
          label: 'Delete',
          icon: 'trash',
          action: async () => { await grid.handleDelete(item.id); },
          variant: 'danger' as const
        }
      ];

      bindRenderedActions(defaultActions);
    }

    row.appendChild(actionsCell);

    return row;
  }

  /**
   * Sanitize action label to create a valid ID
   */
export function sanitizeActionId(grid: any, label: string): string {
    return label.toLowerCase().replace(/[^a-z0-9]/g, '-');
  }

  /**
   * Handle delete action
   */
export async function handleDelete(grid: any, id: string): Promise<void> {
    try {
      await executeStructuredDelete({
        endpoint: `${grid.config.apiEndpoint}/${id}`,
        confirmMessage: 'Are you sure you want to delete this item?',
        confirmTitle: 'Confirm Delete',
        onSuccess: async () => {
          await grid.refresh();
        },
        onError: (error) => {
          grid.showError(formatStructuredErrorForDisplay(error, 'Delete failed'));
        },
        reconcileOnDomainFailure: async () => {
          await grid.refresh();
        },
        notifier: {
          confirm: async (message, options) => grid.confirmAction(message, options),
        },
      });
    } catch (error) {
      logger.error('Error deleting item:', error);
      if (!isHandledActionError(error)) {
        grid.showError(error instanceof Error ? error.message : 'Failed to delete item');
      }
    }
  }

  /**
   * Update pagination UI
   */
export function updatePaginationUI(grid: any, data: ApiResponse): void {
    const total = grid.getResponseTotal(data) ?? grid.state.totalRows;
    const offset = grid.state.perPage * (grid.state.currentPage - 1);
    const start = total === 0 ? 0 : offset + 1;
    const end = Math.min(offset + grid.state.perPage, total);

    const startEl = document.querySelector(grid.selectors.tableInfoStart);
    const endEl = document.querySelector(grid.selectors.tableInfoEnd);
    const totalEl = document.querySelector(grid.selectors.tableInfoTotal);
    const summaryEl = grid.selectors.tableInfoSummary
      ? document.querySelector(grid.selectors.tableInfoSummary)
      : null;

    if (startEl) startEl.textContent = formatPaginationNumber(grid, start);
    if (endEl) endEl.textContent = formatPaginationNumber(grid, end);
    if (totalEl) totalEl.textContent = formatPaginationNumber(grid, total);
    if (summaryEl) {
      const summary = formatPaginationSummary(grid, start, end, total);
      if (summary !== null) summaryEl.textContent = summary;
    }

    grid.renderPaginationButtons(total);
  }

  /**
   * Render pagination buttons
   */
export function renderPaginationButtons(grid: any, total: number): void {
    const container = document.querySelector(grid.selectors.paginationContainer);
    if (!container) return;

    const semantic = grid.config.pagination?.mode === 'semantic';
    const pagination = container.closest?.('[data-datagrid-pagination]') || container;
    pagination.classList?.toggle('admin-datagrid__pagination--presented', semantic);

    const totalPages = Math.ceil(total / grid.state.perPage);
    if (totalPages <= 1) {
      container.innerHTML = '';
      return;
    }

    const current = grid.state.currentPage;
    const buttons = semantic
      ? renderSemanticPaginationButtons(grid, totalPages, current)
      : renderLegacyPaginationButtons(totalPages, current);

    container.innerHTML = buttons.join('');

    // Bind click handlers
    container.querySelectorAll('[data-page]').forEach((btn) => {
      btn.addEventListener('click', async () => {
        const page = parseInt((btn as HTMLElement).dataset.page || '1', 10);
        if (page >= 1 && page <= totalPages) {
          grid.state.currentPage = page;
          grid.pushStateToURL();
          if (grid.config.behaviors?.pagination) {
            await grid.config.behaviors.pagination.onPageChange(page, grid);
          } else {
            await grid.refresh();
          }
        }
      });
    });
  }

function renderSemanticPaginationButtons(grid: any, totalPages: number, current: number): string[] {
    const buttons: string[] = [];
    const labels = {
      previous: resolvePaginationLabel(grid.config.pagination?.labels?.previous, 'Previous'),
      next: resolvePaginationLabel(grid.config.pagination?.labels?.next, 'Next'),
      previousPage: resolvePaginationLabel(grid.config.pagination?.labels?.previousPage, 'Previous page'),
      nextPage: resolvePaginationLabel(grid.config.pagination?.labels?.nextPage, 'Next page'),
      page: resolvePaginationLabel(grid.config.pagination?.labels?.page, 'Page {page}'),
    };

    // Previous button
    buttons.push(`
      <button type="button"
              data-page="${current - 1}"
              aria-label="${escapeAttr(labels.previousPage)}"
              ${current === 1 ? 'disabled' : ''}
              class="admin-datagrid__page-button admin-datagrid__page-button--boundary">
        <span>${escapeHTML(labels.previous)}</span>
      </button>
    `);

    // Page numbers retain first/last reachability and communicate skipped ranges.
    for (const item of paginationWindow(totalPages, current)) {
      if (item === 'ellipsis') {
        buttons.push(`<span class="admin-datagrid__page-ellipsis" aria-hidden="true">${paginationEllipsisIcon}</span>`);
        continue;
      }
      const isActive = item === current;
      const formattedPage = formatPaginationNumber(grid, item);
      const pageLabel = labels.page.includes('{page}')
        ? labels.page.replace('{page}', formattedPage)
        : `${labels.page} ${formattedPage}`;
      buttons.push(`
        <button type="button"
                data-page="${item}"
                aria-label="${escapeAttr(pageLabel)}"
                ${isActive ? 'aria-current="page"' : ''}
                class="admin-datagrid__page-button admin-datagrid__page-button--page${isActive ? ' admin-datagrid__page-button--active' : ''}">
          ${escapeHTML(formattedPage)}
        </button>
      `);
    }

    // Next button
    buttons.push(`
      <button type="button"
              data-page="${current + 1}"
              aria-label="${escapeAttr(labels.nextPage)}"
              ${current === totalPages ? 'disabled' : ''}
              class="admin-datagrid__page-button admin-datagrid__page-button--boundary">
        <span>${escapeHTML(labels.next)}</span>
      </button>
    `);

    return buttons;
  }

function renderLegacyPaginationButtons(totalPages: number, current: number): string[] {
  const buttons: string[] = [];

  buttons.push(`
    <button type="button"
            data-page="${current - 1}"
            aria-label="Previous page"
            ${current === 1 ? 'disabled' : ''}
            class="admin-datagrid__page-button min-h-[38px] min-w-[38px] py-2 px-2.5 inline-flex justify-center items-center gap-x-1.5 text-sm rounded-lg text-gray-800 hover:bg-gray-100 focus:outline-none focus:bg-gray-100 disabled:opacity-50 disabled:pointer-events-none">
      <svg class="shrink-0 size-3.5" xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
        <path d="m15 18-6-6 6-6"></path>
      </svg>
      <span>Previous</span>
    </button>
  `);

  for (const item of paginationWindow(totalPages, current)) {
    if (item === 'ellipsis') {
      buttons.push('<span class="admin-datagrid__page-ellipsis min-w-[24px] text-center text-gray-500" aria-hidden="true">…</span>');
      continue;
    }
    const isActive = item === current;
    buttons.push(`
      <button type="button"
              data-page="${item}"
              aria-label="Page ${item}"
              ${isActive ? 'aria-current="page"' : ''}
              class="min-h-[38px] min-w-[38px] flex justify-center items-center ${
                isActive
                  ? 'bg-gray-200 text-gray-800 focus:outline-none focus:bg-gray-300'
                  : 'text-gray-800 hover:bg-gray-100 focus:outline-none focus:bg-gray-100'
              } admin-datagrid__page-button py-2 px-3 text-sm rounded-lg">
        ${item}
      </button>
    `);
  }

  buttons.push(`
    <button type="button"
            data-page="${current + 1}"
            aria-label="Next page"
            ${current === totalPages ? 'disabled' : ''}
            class="admin-datagrid__page-button min-h-[38px] min-w-[38px] py-2 px-2.5 inline-flex justify-center items-center gap-x-1.5 text-sm rounded-lg text-gray-800 hover:bg-gray-100 focus:outline-none focus:bg-gray-100 disabled:opacity-50 disabled:pointer-events-none">
      <span>Next</span>
      <svg class="shrink-0 size-3.5" xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
        <path d="m9 18 6-6-6-6"></path>
      </svg>
    </button>
  `);

  return buttons;
}

function resolvePaginationLabel(value: unknown, fallback: string): string {
  return typeof value === 'string' && value.trim() ? value.trim() : fallback;
}

function formatPaginationSummary(grid: any, start: number, end: number, total: number): string | null {
  const templates = grid.config.pagination?.labels?.summary;
  if (!templates || typeof templates !== 'object') return null;

  let category = total === 1 ? 'one' : 'other';
  try {
    category = new Intl.PluralRules(grid.config.pagination?.locale).select(total);
  } catch {
    // Invalid or unsupported locale values retain deterministic English-style fallback.
  }
  const template = resolvePaginationLabel(templates[category], resolvePaginationLabel(templates.other, ''));
  if (!template) return null;

  const values: Record<string, string> = {
    start: formatPaginationNumber(grid, start),
    end: formatPaginationNumber(grid, end),
    total: formatPaginationNumber(grid, total),
  };
  return template.replace(/\{(start|end|total)\}/g, (_match, key) => values[key]);
}

export function formatPaginationNumber(grid: any, value: number): string {
  const locale = grid.config.pagination?.locale;
  if (!locale) return String(value);
  try {
    return new Intl.NumberFormat(locale).format(value);
  } catch {
    return String(value);
  }
}

export function paginationWindow(totalPages: number, currentPage: number): Array<number | 'ellipsis'> {
  const total = Math.max(0, Math.floor(totalPages));
  const current = Math.min(Math.max(1, Math.floor(currentPage)), Math.max(total, 1));
  if (total <= 7) return Array.from({ length: total }, (_value, index) => index + 1);
  if (current <= 4) return [1, 2, 3, 4, 5, 'ellipsis', total];
  if (current >= total - 3) return [1, 'ellipsis', total - 4, total - 3, total - 2, total - 1, total];
  return [1, 'ellipsis', current - 1, current, current + 1, 'ellipsis', total];
}
