const logger = createLogger("DataGrid");

export function adoptSemanticPresentation(grid: any): void {
  const table = grid.tableEl as HTMLTableElement | null;
  if (!table || !table.classList || typeof table.closest !== 'function') return;

  table.classList.add('admin-datagrid__table');
  const surface = table.closest<HTMLElement>('[data-datagrid-surface]') || table;
  surface.classList.add('admin-datagrid');

  const header = table.querySelector('thead');
  header?.classList.add('admin-datagrid__header');
  header?.querySelectorAll('th').forEach((cell) => {
    cell.classList.add('admin-datagrid__header-cell');
  });

  const body = table.querySelector('tbody');
  body?.classList.add('admin-datagrid__body');

  table.querySelectorAll<HTMLInputElement | HTMLSelectElement>(grid.selectors.filterRow).forEach((control) => {
    control.classList.add('admin-datagrid__filter-control');
    const row = control.closest('tr');
    row?.classList.add('admin-datagrid__filter-row');
    row?.querySelectorAll('th').forEach((cell) => {
      cell.classList.add('admin-datagrid__header-cell');
    });
  });

  const searchInput = document.querySelector<HTMLElement>(grid.selectors.searchInput);
  searchInput?.closest<HTMLElement>('[data-datagrid-toolbar]')?.classList.add(
    'admin-surface-card',
    'admin-datagrid__toolbar',
  );

  document.querySelector<HTMLElement>('[data-datagrid-filter-panel]')?.classList.add(
    'admin-surface-card',
    'admin-datagrid__filter-panel',
  );

  const paginationControls = document.querySelector<HTMLElement>(grid.selectors.paginationContainer);
  const pagination = paginationControls?.closest<HTMLElement>('[data-datagrid-pagination]') || paginationControls;
  pagination?.classList.add('admin-surface-card', 'admin-datagrid__pagination');
  pagination?.classList.toggle(
    'admin-datagrid__pagination--presented',
    grid.config.pagination?.mode === 'semantic',
  );
  paginationControls?.classList.add('admin-datagrid__pagination-controls');

  for (const selector of [
    grid.selectors.tableInfoStart,
    grid.selectors.tableInfoEnd,
    grid.selectors.tableInfoTotal,
    grid.selectors.tableInfoSummary,
  ]) {
    const value = document.querySelector<HTMLElement>(selector);
    value?.classList.add('admin-datagrid__pagination-text');
    value?.parentElement?.classList.add('admin-datagrid__pagination-text');
  }
  document.querySelector<HTMLElement>(grid.selectors.perPageSelect)
    ?.parentElement
    ?.classList.add('admin-datagrid__pagination-text');
}

export function bindSearchInput(grid: any): void {
    const input = document.querySelector<HTMLInputElement>(grid.selectors.searchInput);
    if (!input) {
      logger.warn(`[DataGrid] Search input not found: ${grid.selectors.searchInput}`);
      return;
    }

    logger.debug(`[DataGrid] Search input bound to: ${grid.selectors.searchInput}`);

    const clearBtn = document.getElementById('clear-search-btn');

    // Toggle clear button visibility
    const toggleClearBtn = () => {
      if (clearBtn) {
        if (input.value.trim()) {
          clearBtn.classList.remove('hidden');
        } else {
          clearBtn.classList.add('hidden');
        }
      }
    };

    input.addEventListener('input', () => {
      toggleClearBtn();

      if (grid.searchTimeout) {
        clearTimeout(grid.searchTimeout);
      }

      grid.searchTimeout = window.setTimeout(async () => {
        logger.debug(`[DataGrid] Search triggered: "${input.value}"`);
        grid.state.search = input.value;
        grid.pushStateToURL();
        if (grid.config.behaviors?.search) {
          await grid.config.behaviors.search.onSearch(input.value, grid);
        } else {
          grid.resetPagination();
          await grid.refresh();
        }
      }, grid.config.searchDelay);
    });

    // Clear button handler
    if (clearBtn) {
      clearBtn.addEventListener('click', async () => {
        input.value = '';
        input.focus();
        toggleClearBtn();

        // Trigger search with empty value
        grid.state.search = '';
        grid.pushStateToURL();
        if (grid.config.behaviors?.search) {
          await grid.config.behaviors.search.onSearch('', grid);
        } else {
          grid.resetPagination();
          await grid.refresh();
        }
      });
    }

    // Initial toggle on page load
    toggleClearBtn();
  }

  /**
   * Bind per-page select
   */
export function bindPerPageSelect(grid: any): void {
    const select = document.querySelector<HTMLSelectElement>(grid.selectors.perPageSelect);
    if (!select) return;

    select.addEventListener('change', async () => {
      grid.state.perPage = parseInt(select.value, 10);
      grid.resetPagination();
      grid.pushStateToURL();
      await grid.refresh();
    });
  }

  /**
   * Bind filter inputs
   */
export function bindFilterInputs(grid: any): void {
    const filterInputs = document.querySelectorAll<HTMLInputElement | HTMLSelectElement>(grid.selectors.filterRow);

    filterInputs.forEach((input) => {
      // Handler function for both input and change events
      const handleFilterChange = async () => {
        const column = input.dataset.filterColumn;
        const inputType = input instanceof HTMLInputElement ? input.type.toLowerCase() : '';
        const inferredOperator = input instanceof HTMLSelectElement
          ? 'eq'
          : (inputType === '' || inputType === 'text' || inputType === 'search' || inputType === 'email' || inputType === 'tel' || inputType === 'url')
            ? 'ilike'
            : 'eq';
        const operator = (input.dataset.filterOperator as any) || inferredOperator;
        const value = input.value;

        if (!column) return;

        // Update filters state
        const existingIndex = grid.state.filters.findIndex(f => f.column === column);
        if (value) {
          const filter: ColumnFilter = { column, operator, value };
          if (existingIndex >= 0) {
            grid.state.filters[existingIndex] = filter;
          } else {
            grid.state.filters.push(filter);
          }
        } else {
          // Remove filter if value is empty
          if (existingIndex >= 0) {
            grid.state.filters.splice(existingIndex, 1);
          }
        }

        grid.pushStateToURL();
        if (grid.config.behaviors?.filter) {
          await grid.config.behaviors.filter.onFilterChange(column, value, grid);
        } else {
          grid.resetPagination();
          await grid.refresh();
        }
      };

      // Bind both input (for text inputs) and change (for selects) events
      input.addEventListener('input', handleFilterChange);
      input.addEventListener('change', handleFilterChange);
    });
  }

  /**
   * Bind column visibility toggle using ColumnManager
   */
export function bindColumnVisibility(grid: any): void {
    const toggleBtn = document.querySelector(grid.selectors.columnToggleBtn);
    const menu = document.querySelector<HTMLElement>(grid.selectors.columnToggleMenu);

    if (!toggleBtn || !menu) return;

    // Initialize ColumnManager to render column items with switches and drag handles
    grid.columnManager = new ColumnManager({
      container: menu,
      grid: grid,
      onToggle: (field, visible) => {
        logger.debug(`[DataGrid] Column ${field} visibility toggled to ${visible}`);
      },
      onReorder: (order) => {
        logger.debug(`[DataGrid] Columns reordered:`, order);
      }
    });
  }

  /**
   * Bind export buttons
   */
export function bindExportButtons(grid: any): void {
    if (!grid.isCapabilityEnabled('export')) return;
    const menu = document.querySelector(grid.selectors.exportMenu);
    if (!menu) return;

    const exportButtons = menu.querySelectorAll<HTMLButtonElement>('[data-export-format]');

    exportButtons.forEach((btn) => {
      btn.addEventListener('click', async () => {
        const format = (btn as HTMLElement).dataset.exportFormat as 'csv' | 'json' | 'excel' | 'pdf';
        if (!format || !grid.config.behaviors?.export) return;

        // Get concurrency mode (default to 'single')
        const concurrency = grid.config.behaviors.export.getConcurrency?.() || 'single';

        // Determine which buttons to disable based on concurrency mode
        const buttonsToDisable: HTMLButtonElement[] = [];
        if (concurrency === 'single') {
          // Disable all export buttons
          exportButtons.forEach(b => buttonsToDisable.push(b));
        } else if (concurrency === 'per-format') {
          // Disable only the clicked button
          buttonsToDisable.push(btn);
        }
        // 'none' mode: no buttons disabled, but clicked button still shows spinner

        // Helper to toggle spinner visibility on a button
        const showSpinner = (b: HTMLButtonElement) => {
          const icon = b.querySelector('.export-icon');
          const spinner = b.querySelector('.export-spinner');
          if (icon) icon.classList.add('hidden');
          if (spinner) spinner.classList.remove('hidden');
        };

        const hideSpinner = (b: HTMLButtonElement) => {
          const icon = b.querySelector('.export-icon');
          const spinner = b.querySelector('.export-spinner');
          if (icon) icon.classList.remove('hidden');
          if (spinner) spinner.classList.add('hidden');
        };

        // Apply loading state to buttons that should be disabled
        buttonsToDisable.forEach(b => {
          b.setAttribute('data-export-loading', 'true');
          b.disabled = true;
          showSpinner(b);
        });

        // For 'none' mode, still show spinner on clicked button (but don't disable)
        const showSpinnerOnly = concurrency === 'none';
        if (showSpinnerOnly) {
          btn.setAttribute('data-export-loading', 'true');
          showSpinner(btn);
        }

        try {
          await grid.config.behaviors.export.export(format, grid);
        } catch (error) {
          // Error already handled by the export behavior (toast shown)
          logger.error('[DataGrid] Export failed:', error);
        } finally {
          // Clear loading state from disabled buttons
          buttonsToDisable.forEach(b => {
            b.removeAttribute('data-export-loading');
            b.disabled = false;
            hideSpinner(b);
          });

          // Clear spinner-only state for 'none' mode
          if (showSpinnerOnly) {
            btn.removeAttribute('data-export-loading');
            hideSpinner(btn);
          }
        }
      });
    });
  }

  /**
   * Bind table sorting
   */
export function bindSorting(grid: any): void {
    if (!grid.tableEl) return;

    // Bind new sort buttons ([data-sort-column])
    const sortButtons = grid.tableEl.querySelectorAll<HTMLButtonElement>('[data-sort-column]');

    sortButtons.forEach((button) => {
      button.addEventListener('click', async (e) => {
        e.preventDefault();
        e.stopPropagation();

        const field = button.dataset.sortColumn;
        if (!field) return;

        logger.debug(`[DataGrid] Sort button clicked for field: ${field}`);

        // Triple-click cycle: none -> asc -> desc -> none -> asc -> ...
        const existing = grid.state.sort.find(s => s.field === field);
        let direction: 'asc' | 'desc' | null = null;

        if (existing) {
          if (existing.direction === 'asc') {
            // asc -> desc
            direction = 'desc';
            existing.direction = direction;
          } else {
            // desc -> none (clear sort)
            grid.state.sort = grid.state.sort.filter(s => s.field !== field);
            direction = null;
            logger.debug(`[DataGrid] Sort cleared for field: ${field}`);
          }
        } else {
          // none -> asc
          direction = 'asc';
          grid.state.sort = [{ field, direction }];
        }

        logger.debug(`[DataGrid] New sort state:`, grid.state.sort);

        grid.pushStateToURL();

        if (direction !== null && grid.config.behaviors?.sort) {
          logger.debug('[DataGrid] Calling custom sort behavior');
          await grid.config.behaviors.sort.onSort(field, direction, grid);
        } else {
          logger.debug('[DataGrid] Calling refresh() for sort');
          await grid.refresh();
        }

        // Update UI
        logger.debug('[DataGrid] Updating sort indicators');
        grid.updateSortIndicators();
      });
    });

    // Also bind legacy sortable headers ([data-sort])
    const sortableHeaders = grid.tableEl.querySelectorAll<HTMLElement>('[data-sort]');

    sortableHeaders.forEach((header) => {
      header.addEventListener('click', async () => {
        const field = header.dataset.sort;
        if (!field) return;

        // Triple-click cycle: none -> asc -> desc -> none -> asc -> ...
        const existing = grid.state.sort.find(s => s.field === field);
        let direction: 'asc' | 'desc' | null = null;

        if (existing) {
          if (existing.direction === 'asc') {
            // asc -> desc
            direction = 'desc';
            existing.direction = direction;
          } else {
            // desc -> none (clear sort)
            grid.state.sort = grid.state.sort.filter(s => s.field !== field);
            direction = null;
          }
        } else {
          // none -> asc
          direction = 'asc';
          grid.state.sort = [{ field, direction }];
        }

        grid.pushStateToURL();

        if (direction !== null && grid.config.behaviors?.sort) {
          await grid.config.behaviors.sort.onSort(field, direction, grid);
        } else {
          await grid.refresh();
        }

        // Update UI
        grid.updateSortIndicators();
      });
    });
  }

  /**
   * Update sort indicators in table headers
   */
export function updateSortIndicators(grid: any): void {
    if (!grid.tableEl) return;

    // Handle both old [data-sort] and new [data-sort-column] buttons
    const sortButtons = grid.tableEl.querySelectorAll<HTMLButtonElement>('[data-sort-column]');

    sortButtons.forEach((button) => {
      const field = button.dataset.sortColumn;
      if (!field) return;

      const sorted = grid.state.sort.find(s => s.field === field);
      const svg = button.querySelector('svg');

      if (svg) {
        // Update button visibility and styling based on sort state
        if (sorted) {
          button.classList.remove('opacity-0');
          button.classList.add('opacity-100');

          // Update icon based on direction
          if (sorted.direction === 'asc') {
            // Show ascending arrow (up arrow only)
            svg.innerHTML = '<path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 15l7-7 7 7" />';
            svg.classList.add('text-blue-600');
            svg.classList.remove('text-gray-400');
          } else {
            // Show descending arrow (down arrow only)
            svg.innerHTML = '<path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 9l-7 7-7-7" />';
            svg.classList.add('text-blue-600');
            svg.classList.remove('text-gray-400');
          }
        } else {
          // Reset to default double arrow
          svg.innerHTML = '<path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 9l4-4 4 4m0 6l-4 4-4-4" />';
          svg.classList.remove('text-blue-600');
          svg.classList.add('text-gray-400');
        }
      }
    });

    // Also handle legacy [data-sort] headers with .sort-indicator
    const headers = grid.tableEl.querySelectorAll<HTMLElement>('[data-sort]');
    headers.forEach((header) => {
      const field = header.dataset.sort;
      const sorted = grid.state.sort.find(s => s.field === field);

      const indicator = header.querySelector('.sort-indicator');
      if (indicator) {
        indicator.textContent = sorted ? (sorted.direction === 'asc' ? '↑' : '↓') : '';
      }
    });
  }

  /**
   * Bind selection checkboxes
   */
export function bindSelection(grid: any): void {
    if (!grid.isCapabilityEnabled('selection')) {
      grid.selectionAbortController?.abort();
      grid.selectionAbortController = null;
      grid.state.selectedRows.clear();
      return;
    }
    if (!grid.tableEl) return;
    if (grid.selectionAbortController) {
      grid.selectionAbortController.abort();
    }
    grid.selectionAbortController = new AbortController();
    const { signal } = grid.selectionAbortController;
    const selectAll = grid.tableEl.querySelector<HTMLInputElement>(grid.selectors.selectAllCheckbox);

    if (selectAll) {
      selectAll.addEventListener('change', () => {
        const checkboxes = grid.tableEl.querySelectorAll<HTMLInputElement>(grid.selectors.rowCheckboxes);
        checkboxes.forEach((cb) => {
          cb.checked = selectAll.checked;
          syncRowSelectionState(cb);
          const id = cb.dataset.id;
          if (id) {
            if (selectAll.checked) {
              grid.state.selectedRows.add(id);
            } else {
              grid.state.selectedRows.delete(id);
            }
          }
        });
        grid.updateBulkActionsBar();
      }, { signal });
    }

    grid.tableEl.addEventListener('change', (event: Event) => {
      const cb = event.target as HTMLInputElement | null;
      if (
        !cb ||
        cb === selectAll ||
        typeof cb.matches !== 'function' ||
        !cb.matches(grid.selectors.rowCheckboxes)
      ) {
        return;
      }
      const id = cb.dataset.id;
      if (id) {
        if (cb.checked) {
          grid.state.selectedRows.add(id);
        } else {
          grid.state.selectedRows.delete(id);
        }
      }
      syncRowSelectionState(cb);
      grid.updateBulkActionsBar();
    }, { signal });

    grid.updateSelectionBindings();
  }

  /**
   * Update selection bindings after rendering
   * This syncs checkbox states with the selectedRows Set
   */
export function updateSelectionBindings(grid: any): void {
    if (!grid.isCapabilityEnabled('selection')) return;
    const checkboxes = grid.tableEl?.querySelectorAll<HTMLInputElement>(grid.selectors.rowCheckboxes) || [];

    checkboxes.forEach((cb) => {
      const id = cb.dataset.id;

      // Sync checkbox state with selectedRows Set
      if (id) {
        cb.checked = grid.state.selectedRows.has(id);
      }
      syncRowSelectionState(cb);
    });
  }

function syncRowSelectionState(checkbox: HTMLInputElement): void {
  const row = checkbox.closest('tr');
  if (!row) return;
  row.dataset.selected = String(checkbox.checked);
  row.setAttribute('aria-selected', String(checkbox.checked));
}

function uniqueElements<T extends HTMLElement>(elements: Array<T | null | undefined>): T[] {
  return Array.from(new Set(elements.filter(Boolean) as T[]));
}

function queryFirst<T extends HTMLElement>(root: ParentNode, selectors: string[]): T | null {
  for (const selector of selectors) {
    const element = root.querySelector<T>(selector);
    if (element) {
      return element;
    }
  }
  return null;
}

function configuredBulkRoot(grid: any): HTMLElement | null {
  const selector = grid?.selectors?.bulkActionsBar;
  if (!selector) {
    return null;
  }
  try {
    return document.querySelector<HTMLElement>(selector);
  } catch (_error) {
    return null;
  }
}

function bulkActionRoot(grid?: any): HTMLElement | null {
  const configured = configuredBulkRoot(grid);
  if (configured && grid?.selectors?.bulkActionsBar !== '#bulk-actions-bar') {
    return configured;
  }
  return queryFirst<HTMLElement>(document, [
    '[data-bulk-action-overlay]',
    '#bulk-actions-overlay',
    '[data-bulk-action-bar="true"]',
  ]) || configured;
}

function bulkActionButtons(grid?: any): HTMLElement[] {
  const root = bulkActionRoot(grid);
  if (root) {
    return Array.from(root.querySelectorAll<HTMLElement>('[data-bulk-action]'));
  }
  return Array.from(document.querySelectorAll<HTMLElement>('[data-bulk-action]'));
}

function bulkSelectionCountElement(grid?: any): HTMLElement | null {
  const root = bulkActionRoot(grid);
  const selectors = ['[data-bulk-selection-count]', '#selected-count', grid?.selectors?.selectedCount].filter(Boolean);
  return (root ? queryFirst<HTMLElement>(root, selectors) : null)
    || queryFirst<HTMLElement>(document, selectors);
}

function bulkClearButtons(grid?: any): HTMLButtonElement[] {
  const root = bulkActionRoot(grid);
  const selectors = ['[data-bulk-clear]', '#bulk-clear-selection', '#clear-selection-btn'];
  const matches = selectors.flatMap((selector) => {
    const scope = root || document;
    return Array.from(scope.querySelectorAll<HTMLButtonElement>(selector));
  });
  if (matches.length) {
    return uniqueElements(matches);
  }
  return uniqueElements(selectors.flatMap((selector) => Array.from(document.querySelectorAll<HTMLButtonElement>(selector))));
}

function bindBulkClearButtons(grid: any): void {
  bulkClearButtons(grid).forEach((clearBtn) => {
    if (clearBtn.dataset.bulkClearBound === 'true') {
      return;
    }
    clearBtn.dataset.bulkClearBound = 'true';
    clearBtn.addEventListener('click', () => {
      grid.clearSelection();
    });
  });
}

function setBulkOverlayVisibility(root: HTMLElement, selectedCount: number): void {
  if (root.hasAttribute('data-selection-count')) {
    root.dataset.selectionCount = String(selectedCount);
  }
  if (selectedCount > 0) {
    root.classList.remove('hidden', 'pointer-events-none', 'translate-y-full', '-translate-y-full');
    root.classList.add('translate-y-0');
    root.removeAttribute('aria-hidden');
    return;
  }

  root.classList.remove('translate-y-0');
  if (root.hasAttribute('data-bulk-action-overlay')) {
    const position = root.dataset.bulkOverlayPosition || (root.classList.contains('top-0') ? 'top' : 'bottom');
    root.classList.add('pointer-events-none', position === 'top' ? '-translate-y-full' : 'translate-y-full');
    root.setAttribute('aria-hidden', 'true');
    return;
  }

  root.classList.add('hidden');
}

function ensureBulkReasonContainer(overlay: HTMLElement | null): HTMLElement | null {
  if (!overlay) {
    return null;
  }
  let container = overlay.querySelector<HTMLElement>('[data-bulk-action-state-reasons]');
  if (container) {
    return container;
  }
  container = document.createElement('div');
  container.dataset.bulkActionStateReasons = 'true';
  container.className = 'hidden mt-3 text-sm text-gray-700';
  overlay.appendChild(container);
  return container;
}

function renderBulkActionReasons(reasons: Array<{ actionId: string; label: string; reason: string }>, grid?: any): void {
  const overlay = bulkActionRoot(grid);
  const container = ensureBulkReasonContainer(overlay);
  if (!container) {
    return;
  }
  if (!reasons.length) {
    container.classList.add('hidden');
    container.innerHTML = '';
    return;
  }
  container.classList.remove('hidden');
  container.innerHTML = reasons.map((entry) => `
    <div data-bulk-action-reason-item="${entry.actionId}" class="mt-1">
      <span class="font-medium">${entry.label}:</span> ${entry.reason}
    </div>
  `).join('');
}

function applyButtonState(button: HTMLElement, state: Record<string, unknown> | null, fallbackLabel: string): { actionId: string; label: string; reason: string } | null {
  const disabled = state?.enabled === false;
  const reason = typeof state?.reason === 'string' ? state.reason.trim() : '';
  button.dataset.disabled = disabled ? 'true' : 'false';
  button.setAttribute('aria-disabled', disabled ? 'true' : 'false');
  button.dataset.bulkState = disabled ? 'disabled' : 'enabled';
  button.classList.toggle('opacity-50', disabled);
  button.classList.toggle('cursor-not-allowed', disabled);
  if (disabled && reason) {
    button.setAttribute('title', reason);
    return {
      actionId: button.dataset.bulkAction || '',
      label: fallbackLabel,
      reason,
    };
  }
  button.removeAttribute('title');
  return null;
}

function applyPendingBulkActionState(grid: any): void {
  const buttons = bulkActionButtons(grid);
  const pendingReason = 'Checking selected records...';
  const reasons: Array<{ actionId: string; label: string; reason: string }> = [];
  buttons.forEach((button) => {
    button.dataset.disabled = 'true';
    button.dataset.bulkState = 'loading';
    button.setAttribute('aria-disabled', 'true');
    button.setAttribute('title', pendingReason);
    button.classList.add('opacity-50', 'cursor-not-allowed');
    reasons.push({
      actionId: button.dataset.bulkAction || '',
      label: button.textContent?.trim() || button.dataset.bulkAction || 'Action',
      reason: pendingReason,
    });
  });
  renderBulkActionReasons(reasons, grid);
}

function currentBulkActionStateConfig(grid: any): Record<string, unknown> | null {
  return normalizeBulkActionStateConfig(grid.bulkActionStateConfig);
}

export function setBulkActionState(grid: any, state: Record<string, any> | null | undefined, config: Record<string, any> | null | undefined): void {
  grid.bulkActionState = normalizeBulkActionStateMap(state);
  grid.bulkActionStateConfig = normalizeBulkActionStateConfig(config);
  grid.applyBulkActionState(grid.bulkActionState);
}

export function applyBulkActionState(grid: any, state: Record<string, any> | null | undefined): void {
  const normalized = normalizeBulkActionStateMap(state);
  grid.bulkActionState = normalized;
  const reasons: Array<{ actionId: string; label: string; reason: string }> = [];
  bulkActionButtons(grid).forEach((button) => {
    const actionId = button.dataset.bulkAction;
    if (!actionId) {
      return;
    }
    const reason = applyButtonState(
      button,
      normalized[actionId] || null,
      button.textContent?.trim() || actionId,
    );
    if (reason) {
      reasons.push(reason);
    }
  });
  renderBulkActionReasons(reasons, grid);
}

async function fetchSelectionSensitiveBulkActionState(grid: any): Promise<void> {
  const config = currentBulkActionStateConfig(grid);
  const endpoint = typeof config?.selection_state_endpoint === 'string'
    ? config.selection_state_endpoint.trim()
    : '';
  if (!endpoint) {
    grid.applyBulkActionState(grid.bulkActionState);
    return;
  }

  const selectedIds = Array.from(grid.state.selectedRows);
  if (!selectedIds.length) {
    grid.applyBulkActionState(grid.bulkActionState);
    return;
  }

  if (grid.bulkActionStateAbortController) {
    grid.bulkActionStateAbortController.abort();
  }
  grid.bulkActionStateAbortController = new AbortController();
  grid.bulkActionStateRequestSeq += 1;
  const requestSeq = grid.bulkActionStateRequestSeq;
  const query = typeof grid.buildQueryString === 'function' ? grid.buildQueryString() : '';
  const url = query ? `${endpoint}${endpoint.includes('?') ? '&' : '?'}${query}` : endpoint;

  try {
    const response = await httpRequest(url, {
      method: 'POST',
      signal: grid.bulkActionStateAbortController.signal,
      json: { ids: selectedIds },
    });
    if (!response.ok) {
      throw new Error(`Bulk action state request failed: ${response.status}`);
    }
    const payload = normalizeBulkActionStateResponse(await response.json());
    if (!payload || requestSeq !== grid.bulkActionStateRequestSeq) {
      return;
    }
    grid.applyBulkActionState({
      ...grid.bulkActionState,
      ...payload.bulk_action_state,
    });
  } catch (error) {
    if (error instanceof Error && error.name === 'AbortError') {
      return;
    }
    logger.warn('[DataGrid] Failed to refresh selection-sensitive bulk action state:', error);
    if (requestSeq === grid.bulkActionStateRequestSeq) {
      grid.applyBulkActionState(grid.bulkActionState);
    }
  }
}

export function syncBulkActionState(grid: any): void {
  if (!grid.isCapabilityEnabled('bulk')) return;
  if (grid.bulkActionStateDebounce) {
    clearTimeout(grid.bulkActionStateDebounce);
    grid.bulkActionStateDebounce = null;
  }

  const config = currentBulkActionStateConfig(grid);
  const selectedCount = grid.state.selectedRows.size;
  if (!config?.selection_sensitive || !config.selection_state_endpoint || selectedCount === 0) {
    if (grid.bulkActionStateAbortController) {
      grid.bulkActionStateAbortController.abort();
      grid.bulkActionStateAbortController = null;
    }
    grid.applyBulkActionState(grid.bulkActionState);
    return;
  }

  applyPendingBulkActionState(grid);
  const debounceMS = typeof config.debounce_ms === 'number' ? config.debounce_ms : 150;
  grid.bulkActionStateDebounce = window.setTimeout(() => {
    grid.bulkActionStateDebounce = null;
    void fetchSelectionSensitiveBulkActionState(grid);
  }, debounceMS);
}

  /**
   * Bind bulk action buttons
   */
export function bindBulkActions(grid: any): void {
    if (!grid.isCapabilityEnabled('bulk')) return;
    const overlay = bulkActionRoot(grid);
    const bulkBase = overlay?.dataset?.bulkBase || '';
    const actionButtons = bulkActionButtons(grid);

    actionButtons.forEach((btn) => {
      btn.addEventListener('click', async () => {
        const el = btn as HTMLElement;
        const actionId = el.dataset.bulkAction;
        if (!actionId) return;
        if (el.getAttribute('aria-disabled') === 'true' || el.dataset.disabled === 'true') {
          return;
        }

        const ids = Array.from(grid.state.selectedRows);
        if (ids.length === 0) {
          grid.notify('Please select items first', 'warning');
          return;
        }

        // 1. Try config.bulkActions first (inline JS config)
        if (grid.config.bulkActions) {
          const bulkActionConfig = grid.config.bulkActions.find(ba => ba.id === actionId);
          if (bulkActionConfig) {
            try {
              await grid.actionRenderer.executeBulkAction(bulkActionConfig, ids);
              grid.clearSelection();
              await grid.refresh();
            } catch (error) {
              logger.error('Bulk action failed:', error);
              const structured = getStructuredActionError(error);
              if (structured?.textCode) {
                await grid.refresh();
              }
              if (!isHandledActionError(error)) {
                grid.showError(error instanceof Error ? error.message : 'Bulk action failed');
              }
            }
            return;
          }
        }

        // 2. Try DOM data-driven config (from server-rendered data-bulk-* attributes)
        if (bulkBase) {
          const endpoint = `${bulkBase}/${actionId}`;
          const confirmMsg = el.dataset.bulkConfirm;
          const payloadRequired = grid.parseDatasetStringArray(el.dataset.bulkPayloadRequired);
          const payloadSchema = grid.parseDatasetObject(el.dataset.bulkPayloadSchema);
          const domConfig = {
            id: actionId,
            label: el.textContent?.trim() || actionId,
            endpoint: endpoint,
            confirm: confirmMsg,
            payloadRequired: payloadRequired,
            payloadSchema: payloadSchema,
          };
          try {
            await grid.actionRenderer.executeBulkAction(domConfig, ids);
            grid.clearSelection();
            await grid.refresh();
          } catch (error) {
            logger.error('Bulk action failed:', error);
            const structured = getStructuredActionError(error);
            if (structured?.textCode) {
              await grid.refresh();
            }
            if (!isHandledActionError(error)) {
              grid.showError(error instanceof Error ? error.message : 'Bulk action failed');
            }
          }
          return;
        }

        // 3. Fall back to behaviors.bulkActions (old system)
        if (grid.config.behaviors?.bulkActions) {
          try {
            await grid.config.behaviors.bulkActions.execute(actionId, ids, grid);
            grid.clearSelection();
          } catch (error) {
            logger.error('Bulk action failed:', error);
            const structured = getStructuredActionError(error);
            if (structured?.textCode) {
              await grid.refresh();
            }
            if (!isHandledActionError(error)) {
              grid.showError(error instanceof Error ? error.message : 'Bulk action failed');
            }
          }
        }
      });
    });

    bindBulkClearButtons(grid);

    // Bind overflow menu toggle
    grid.bindOverflowMenu();
  }

  /**
   * Bind overflow menu toggle (three-dot "More" button)
   */
export function bindOverflowMenu(grid: any): void {
    const moreBtn = document.getElementById('bulk-more-btn');
    const menu = document.getElementById('bulk-overflow-menu');
    if (!moreBtn || !menu) return;

    moreBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      menu.classList.toggle('hidden');
    });

    // Close on outside click
    document.addEventListener('click', () => {
      menu.classList.add('hidden');
    });

    // Close on Escape
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') {
        menu.classList.add('hidden');
      }
    });

    // Prevent menu clicks from closing the menu
    menu.addEventListener('click', (e) => {
      e.stopPropagation();
    });
  }

  /**
   * Update bulk actions bar visibility with animation
   */
export function updateBulkActionsBar(grid: any): void {
    if (!grid.isCapabilityEnabled('bulk')) return;
    const overlay = bulkActionRoot(grid);
    const countEl = bulkSelectionCountElement(grid);
    const selectedCount = grid.state.selectedRows.size;

    if (!overlay || !countEl) {
      return;
    }

    // Update count
    countEl.textContent = String(selectedCount);

    setBulkOverlayVisibility(overlay, selectedCount);
    if (selectedCount > 0) {
      void overlay.offsetHeight;
    }
    grid.syncBulkActionState();
  }

  /**
   * Bind clear selection button
   */
export function bindBulkClearButton(grid: any): void {
    if (!grid.isCapabilityEnabled('bulk')) return;
    bindBulkClearButtons(grid);
  }

  /**
   * Clear all selections
   */
export function clearSelection(grid: any): void {
    if (!grid.isCapabilityEnabled('selection')) return;
    logger.debug('[DataGrid] Clearing selection...');
    grid.state.selectedRows.clear();

    // Uncheck the "select all" checkbox in the table header
    const selectAllCheckbox = grid.tableEl?.querySelector<HTMLInputElement>(grid.selectors.selectAllCheckbox);
    if (selectAllCheckbox) {
      selectAllCheckbox.checked = false;
    }

    grid.updateBulkActionsBar();
    grid.updateSelectionBindings();
  }

  /**
   * Position dropdown menu intelligently based on available space
   */
export function positionDropdownMenu(grid: any, trigger: HTMLElement, menu: HTMLElement): void {
    defaultActionMenuPositioner({ trigger, menu });
  }

  /**
   * Bind dropdown toggles
   */
export function bindDropdownToggles(grid: any): void {
    // Ensure we don't stack global listeners across in-page navigations.
    if (grid.actionMenuController) {
      grid.actionMenuController.destroy();
      grid.actionMenuController = null;
    }
    if (grid.dropdownAbortController) {
      grid.dropdownAbortController.abort();
    }
    grid.dropdownAbortController = new AbortController();
    const { signal } = grid.dropdownAbortController;

    // Existing dropdown toggles (column visibility, export, etc.)
    // Defensive: ensure all dropdown menus start hidden
    document.querySelectorAll('[data-dropdown-toggle]').forEach((toggle) => {
      const targetId = (toggle as HTMLElement).dataset.dropdownToggle;
      const target = document.getElementById(targetId || '');
      if (target && !target.classList.contains('hidden')) {
        target.classList.add('hidden');
      }
    });

    const closeGenericDropdowns = (restoreFocus = false) => {
      document.querySelectorAll('[data-dropdown-toggle]').forEach((toggle) => {
        const targetId = (toggle as HTMLElement).dataset.dropdownToggle;
        const target = document.getElementById(targetId || '');
        if (target) {
          target.classList.add('hidden');
          toggle.setAttribute('aria-expanded', 'false');
          if (restoreFocus && target.getAttribute('data-dropdown-open') === 'true') {
            (toggle as HTMLElement).focus();
          }
          target.removeAttribute('data-dropdown-open');
        }
      });
    };

    addDelegatedEventListener(document, 'click', '[data-dropdown-toggle]', (event, toggle) => {
      const targetId = toggle.dataset.dropdownToggle;
      const target = document.getElementById(targetId || '');
      const isDisabledExportDropdown = !grid.isCapabilityEnabled('export') && (
        toggle.matches(grid.selectors.exportBtn) ||
        target?.matches(grid.selectors.exportMenu)
      );
      if (isDisabledExportDropdown) return;

      event.stopPropagation();

      if (target) {
        const opening = target.classList.contains('hidden');
        document.querySelectorAll('[data-dropdown-toggle]').forEach((otherToggle) => {
          const otherId = (otherToggle as HTMLElement).dataset.dropdownToggle;
          const otherTarget = document.getElementById(otherId || '');
          if (otherTarget && otherTarget !== target) {
            otherTarget.classList.add('hidden');
            otherToggle.setAttribute('aria-expanded', 'false');
            otherTarget.removeAttribute('data-dropdown-open');
          }
        });

        target.classList.toggle('hidden');
        toggle.setAttribute('aria-expanded', String(opening));
        if (opening) {
          target.setAttribute('data-dropdown-open', 'true');
          const focusTarget = target.querySelector<HTMLElement>(
            '[role="option"], [role="menuitem"], button:not([disabled]), input:not([disabled]), select:not([disabled]), [tabindex]:not([tabindex="-1"])'
          );
          focusTarget?.focus();
        } else {
          target.removeAttribute('data-dropdown-open');
          toggle.focus();
        }
      }
    }, { signal });

    document.addEventListener('click', (e) => {
      const target = e.target as Element | null;
      const clickedInsideGenericDropdown = target && typeof target.closest === 'function'
        ? target.closest('[data-dropdown-toggle], #column-toggle-menu, #export-menu')
        : null;
      if (!clickedInsideGenericDropdown) {
        closeGenericDropdowns();
      }
    }, { signal });

    const actionMenuRoot = grid.tableEl ?? document;
    grid.actionMenuController = initActionMenus(actionMenuRoot, {
      containerSelector: '[data-dropdown], .actions-dropdown',
      triggerSelector: '[data-dropdown-trigger], .actions-menu-trigger',
      menuSelector: '.actions-menu',
      itemSelector: '[role="menuitem"], .action-item',
      outsideIgnoreSelector: '[data-dropdown-toggle], #column-toggle-menu, #export-menu',
      positionMenu: ({ trigger, menu }) => {
        grid.positionDropdownMenu(trigger, menu);
      },
      portal: true,
      signal,
    });

    // ESC key closes all generic dropdowns. Row action menus are closed by the shared primitive.
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') {
        closeGenericDropdowns(true);
      }
    }, { signal });
  }

  /**
   * Show error message using notifier
   */
export function showError(grid: any, message: string): void {
    logger.error(message);
    grid.notifier.error(message);
  }

  /**
   * Show notification using notifier
   */
export function notify(grid: any, message: string, type: 'success' | 'error' | 'warning' | 'info'): void {
    grid.notifier.show({ message, type });
  }

  /**
   * Show confirmation dialog using notifier
   */
export async function confirmAction(grid: any, message: string): Promise<boolean> {
    return grid.notifier.confirm(message);
  }

  /**
   * Extract error message from Response or Error
   */
export async function extractError(grid: any, error: unknown): Promise<string> {
    if (error instanceof Response) {
      return extractErrorMessage(error);
    }
    if (error instanceof Error) {
      return error.message;
    }
    return 'An unexpected error occurred';
  }

export function parseDatasetStringArray(grid: any, raw: string | undefined): string[] | undefined {
    if (!raw) {
      return undefined;
    }
    try {
      const parsed = JSON.parse(raw) as unknown;
      if (!Array.isArray(parsed)) {
        return undefined;
      }
      const result = parsed
        .map((item) => (typeof item === 'string' ? item.trim() : ''))
        .filter((item) => item.length > 0);
      return result.length > 0 ? result : undefined;
    } catch (error) {
      logger.warn('[DataGrid] Failed to parse bulk payload_required:', error);
      return undefined;
    }
  }

export function parseDatasetObject(grid: any, raw: string | undefined): Record<string, unknown> | undefined {
    if (!raw) {
      return undefined;
    }
    try {
      const parsed = JSON.parse(raw) as unknown;
      if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
        return undefined;
      }
      return parsed as Record<string, unknown>;
    } catch (error) {
      logger.warn('[DataGrid] Failed to parse bulk payload_schema:', error);
      return undefined;
    }
  }
